Contract GenerateLoanLetterAndAgreementModule::generateLoanAgreement(): Boolean {
          definition:
          obs:LoanRequest = LoanRequest.allInstance()->any(o | o = currentLoanRequest)

            precondition:
          obs.oclIsUndefined() = false

            postcondition:
          let newLoanAgreement: LoanAgreement in (newLoanAgreement.oclIsNew() and newLoanAgreement.Content = \"Loan Agreement\" and obs.AttachedLoanAgreement = newLoanAgreement and currentLoanAgreement = newLoanAgreement and result = true)

        }
